import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"革","description":"周易集解 - 革","frontmatter":{"title":"革","description":"周易集解 - 革"},"headers":[],"relativePath":"zh/classics/jijie/049.md","filePath":"zh/classics/jijie/049.md"}'),l={name:"zh/classics/jijie/049.md"};function p(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="革" tabindex="-1">革 <a class="header-anchor" href="#革" aria-label="Permalink to “革”">​</a></h1><h2 id="革-1" tabindex="-1">革 <a class="header-anchor" href="#革-1" aria-label="Permalink to “革”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>革，已日乃孚，元亨利貞，悔亡。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：井道不可不革也，故受之以革。</p><p>韓康伯曰：井久則濁穢，宜革易其故也。</p><p>鄭玄曰：革，改也。水火相息而更用事，猶王者受命，改正朔，易服色，故謂之革也。</p><p>虞翻曰：遯上之初，與蒙旁通。悔亡，謂四也。四失正，動得位，故悔亡。離為日，孚謂坎。四動體離，五在坎中，故已日乃孚。以成既濟，乾道變化，各正性命，保合太和，乃利貞，故｢元亨利貞，悔亡｣矣。與《乾 · 彖》同義也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：革，水火相息，二女同居，其志不相得，曰革。已日乃孚，革而信之。文明以說，大亨以正，革而當，其悔乃亡。天地革而四時成。湯武革命，順乎天而應乎人。革之時大矣哉。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>虞翻曰：息，長也。離為火，兌為水。《繫》曰：潤之以風雨。風，巽。雨，兌也。四革之正，坎見，故獨於此稱水也。</p><p>虞翻曰：二女，離兌。體同人象。蒙艮為居，故二女同居。四變體兩坎象，二女有志。離火志上，兌水志下。故其志不相得。坎為志也。</p><p>乾寶曰：天命已至之日也。乃孚，大信著也。武王陳兵孟津之上，諸侯不期而會者八百國，皆曰紂可伐矣。武王曰：爾未知天命，未可也。還歸。二年，紂殺比干，囚箕子，爾乃伐之。所謂｢已日乃孚，革而信｣也。</p><p>虞翻曰：文明謂離。說，兌也。大亨謂乾。四動成既濟定，故｢大亨以正，革而當位，故悔乃亡｣也。</p><p>虞翻曰：謂五位成。乾為天。蒙坤為地，震春。兌秋。四之正，坎冬離夏，則四時具。坤革而成乾，故天地革而四時成也。</p><p>虞翻曰：湯武謂乾，乾為聖人。天謂五，人謂三。四動，順五應三，故順天應人。巽為命也。</p><p>乾寶曰：革天地，成四時；誅二叔，除民害；天下定，武功成，故大矣哉也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：澤中有火，革。君子以治曆明時。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：火就燥，澤資溼，二物不相得，終宜易之，故曰｢澤中有火，革｣也。</p><p>虞翻曰：君子，遯乾也。曆象謂日月星辰也。離為明，坎為月。離為日，蒙艮為星。四動成坎離，日月得正，天地革而四時成。故君子以治曆明時也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，鞏用黃牛之革。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>乾寶曰：鞏，固也。離為牝牛。離爻本坤，黃牛之象也。在革之初，而無應據，未可以動，故曰鞏用黃牛之革。此喻文王雖有聖德，天下歸周，三分有二，而服事殷，其義也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：鞏用黃牛，不可以有為也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：得位無應，動而必凶，故不可以有為也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，已日乃革之，徵吉，無咎。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>荀爽曰：日以喻君也。謂五已居位為君。二乃革意去三應五。故曰已日乃革之。上行應五，去卑事尊，故曰徵吉無咎也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：已日革之，行有嘉也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：得位以正，居中有應。則是湯武行善，桀紂行惡，各終其日，然後革之，故曰已日乃革之，行此有嘉。</p><p>虞翻曰：嘉謂五，乾為嘉。四動承五，故行有嘉矣。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，徵凶，貞厲。革言三就，有孚。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>荀爽曰：三應於上，欲往應之，為陰所乘故曰徵凶。若正居三，而據二陰，則五來危之，故曰貞厲也。</p><p>翟玄曰：言三就上，二陽乾得共有信，據於二陰，故曰革言三就，有孚於二矣。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：革言三就，又何之矣。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：雖得位以正，而未可頓革，故以言就之。夫安者有其危也。故受命之君，雖誅元惡，未改其命者。以即行改命，習俗不安，故曰徵凶。猶以正自危，故曰貞厲。是以武王克紂，不即行周命，乃反商政，一就也。釋箕子囚，封比干墓，式商容閭，二就也。散鹿台之財，發鉅橋之粟，大賚於四海，三就也。故曰革言三就。</p><p>虞翻曰：四動成既濟定，故又何之矣。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，悔亡，有孚，改命吉。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：革而當，其悔乃亡。孚謂五也。巽為命。四動五坎改巽，故改命吉。四乾為君，進退無恆，在離焚棄，體大過死，傳以比桀紂。湯武革命，順天應人，故改命吉也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：改命之吉，信志也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：四動成坎，故信志也。</p><p>乾寶曰：爻入上象，喻紂之郊也。以逆取而四海順之。動凶器而前歌后舞。故曰悔亡也。中流而白魚入舟，天命信矣，故曰有孚。甲子夜陣雨甚，至水德賓服之祥也。故曰｢改命之吉，信志也｣。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，大人虎變，未占有孚。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：乾為大人，謂五也。蒙坤為虎變。傳論湯武以坤臣為君。占，視也。離為占。四未之正，五未在坎，故未占有孚也。</p><p>馬融曰：大人虎變，虎變威德折衝萬里，望風而信。以喻舜舞乾羽，而有苗自服；周公修文德，越裳獻雉，故曰未占有孚矣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：大人虎變，其文柄也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>宋衷曰：陽稱大，五以陽居中，故曰大人。兌為白虎，九者變爻，故曰｢大人虎變，其文炳也｣。</p><p>虞翻曰：乾為大明，動成離，故其文炳也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，君子豹變，小人革面，徵凶。居貞吉。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：蒙艮為君子，為豹。從乾而更。故君子豹變也。</p><p>虞翻曰：陰稱小人也。面謂四。革為離，以順承五。故小人革面。乘陽失正，故徵凶。得位，故居貞吉。蒙艮為居也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：君子豹變，其文蔚也。小人革面，順以從君也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>陸績曰：兌之陽爻稱虎，陰爻稱豹。豹，虎類而小者也。君子小於大人。故曰豹變，其文蔚也。</p><p>虞翻曰：蔚，蔇也。兌小。故其文蔚也。</p><p>虞翻曰：乾，君，謂五也。四變順五，故順以從君也。</p><p>乾寶曰：君子、大賢，次聖之人。謂若大公周召之徒也。豹，虎之屬。蔚，炳之次也。君聖臣賢，殷之頑民，皆改志從化，故曰小人革面。天下既定，必倒載干戈，包之以虎皮。將卒之士，使為諸侯，故曰徵凶，居貞吉。得正有應，君子之象也。</p><p>案：兌為口，乾為首，今口在首上，面之象也。乾為大人，虎變也。兌為小人，革面也。</p>',83)])])}const m=e(l,[["render",p]]);export{b as __pageData,m as default};
